alter table public.record_relief_uploads add column if not exists packet_id uuid;create table if not exists public.record_relief_case_packets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,case_id uuid references public.record_relief_cases(id) on delete set null,status text not null default 'collecting' check(status in('collecting','needs_review','confirmed','evaluated','archived')),merged_extraction jsonb,conflicts jsonb not null default '[]'::jsonb,confirmed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.record_relief_uploads drop constraint if exists record_relief_uploads_packet_fk;alter table public.record_relief_uploads add constraint record_relief_uploads_packet_fk foreign key(packet_id) references public.record_relief_case_packets(id) on delete set null;create index if not exists record_relief_uploads_packet_idx on public.record_relief_uploads(packet_id);alter table public.record_relief_case_packets enable row level security;drop policy if exists "members read own relief packets" on public.record_relief_case_packets;drop policy if exists "members create own relief packets" on public.record_relief_case_packets;drop policy if exists "members update own relief packets" on public.record_relief_case_packets;create policy "members read own relief packets" on public.record_relief_case_packets for select using(auth.uid()=user_id);create policy "members create own relief packets" on public.record_relief_case_packets for insert with check(auth.uid()=user_id);create policy "members update own relief packets" on public.record_relief_case_packets for update using(auth.uid()=user_id) with check(auth.uid()=user_id);